	document.querySelectorAll("[data-plan-toggle]").forEach(function(button){button.addEventListener("click",function(event){event.preventDefault();event.stopPropagation();var id=button.getAttribute("data-plan-toggle"),details=document.querySelector('[data-plan-details="'+selectorValue(id)+'"]');if(!details)return;var open=details.hidden;details.hidden=!open;button.classList.toggle("open",open);button.firstChild.nodeValue=open?"Ocultar detalles ":"Ver todo lo que incluye "})});
	document.querySelectorAll("[data-goal-pill]").forEach(function(button){button.addEventListener("click",function(){var goal=button.getAttribute("data-goal-pill"),recommended=document.querySelector('.nxPlanCard[data-plan-goal="'+selectorValue(goal)+'"]:not([hidden]) input[name="selected_plan"]');if(recommended)choosePlan(recommended.value,false);renderPlanPickerState()})});
	var unoToggle=document.getElementById("unoToggle"),unoDetails=document.getElementById("unoDetails");if(unoToggle&&unoDetails)unoToggle.addEventListener("click",function(){unoDetails.hidden=!unoDetails.hidden;unoToggle.querySelector("b").textContent=unoDetails.hidden?"Ver plan ⌄":"Ocultar ⌃"});
	document.querySelectorAll("[data-uno-plan]").forEach(function(button){button.addEventListener("click",function(){var id=button.getAttribute("data-uno-plan");if(id)choosePlan(id,true);else showError("Nextfor Uno queda listo como opción comercial. Para este demo seguimos con los planes principales conectados a Wompi.")})});
	document.querySelectorAll("[data-signature-request]").forEach(function(button){button.addEventListener("click",function(){showError("Nextfor Signature se solicita con el equipo comercial. Este setup guarda el interés sin activar un bot automáticamente.")})});
	function filterPlansForBot(){document.querySelectorAll("[data-plan-bot]").forEach(function(label){if(label.classList.contains("nxPlanCard")){label.hidden=false;return}var bot=String(label.getAttribute("data-plan-bot")||"");label.hidden=!!bot&&bot!==SELECTED_BOT_ID});renderPlanPickerState();}
	document.querySelectorAll('input[name="selected_bot"]').forEach(function(input){input.addEventListener("change",function(){SELECTED_BOT_ID=input.value;filterPlansForBot();scheduleAutoSave();renderSetupSummary();renderActivationBlueprint();showError("")})});
	document.querySelectorAll('input[name="payment_choice"]').forEach(function(input){input.addEventListener("change",function(){SELECTED_PAYMENT_CHOICE=input.value;scheduleAutoSave();renderActivationBlueprint();showError("")})});
var shopifyConnectButton=document.getElementById("shopifyConnectButton");if(shopifyConnectButton)shopifyConnectButton.addEventListener("click",function(event){event.preventDefault();if(busy)return;var answers=collect();if(String(getPath(answers,"commerce.platform")||"")!=="shopify"){showError("Elige Shopify como plataforma antes de conectar la app.");return}var externalTab=prepareOnboardingExternalTab("Shopify");if(!externalTab){showError("Tu navegador bloqueó la nueva pestaña. Permite ventanas emergentes para Nextfor y vuelve a intentar.");return}setBusy(true,"Guardando y abriendo Shopify…");showError("");request("draft").then(function(body){INITIAL=body.onboarding;dirty=false;if(!navigateOnboardingExternalTab(externalTab,shopifyConnectButton.href))throw new Error("No pudimos abrir la pestaña de Shopify.");document.getElementById("actionMessage").textContent="Shopify se abrió en una pestaña nueva. Este setup permanecerá abierto.";setBusy(false)}).catch(function(error){closeOnboardingExternalTab(externalTab);showError(error.message);document.getElementById("actionMessage").textContent="No pudimos guardar antes de conectar Shopify.";setBusy(false)})});
